type OrderStatus = "Tất cả" | "Đang giao" | "Đã giao";

interface OrderItem {
  id: number;
  orderItemId?: number;
  name: string;
  image: string;
  price: number;
  quantity: number;
  review?: ApiReview | null;
}

interface Order {
  id: string;
  rawStatus?: string;
  date: string;
  status: Exclude<OrderStatus, "Tất cả">;
  address: string;
  paymentMethod: string;
  shipping: number;
  tax: number;
  discount: number;
  items: OrderItem[];
}

interface ApiOrderItem {
  id: number;
  product_id: number | null;
  product_name: string;
  product_image: string | null;
  price: number;
  quantity: number;
  review?: ApiReview | null;
}

interface ApiOrder {
  order_number: string;
  created_at: string;
  status: string;
  payment_method: string;
  customer_address: string;
  recipient_address: string | null;
  shipping_fee: number;
  tax: number;
  discount: number;
  items: ApiOrderItem[];
}

interface ApiReview {
  id: number;
  rating: number;
  content?: string | null;
}

