"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useCart } from "@/context/CartContext";
import { useFavorites } from "@/context/FavoritesContext";
import { cn, formatVND, productImageUrl } from "@/lib/utils";
import type { Product } from "@/types/product";
import { Check, Eye, Heart, ShoppingCart } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useState } from "react";

export default function ProductCard({ product }: { product: Product }) {
  const { addToCart } = useCart();
  const { toggleFavorite, isFavorite } = useFavorites();
  const isLiked = isFavorite(product.id);
  const [imageError, setImageError] = useState(false);
  const [isAdding, setIsAdding] = useState(false);
  const [justAdded, setJustAdded] = useState(false);
  const imageUrl = productImageUrl(product.image);
  const stock = product.stock ?? 100;
  const isOutOfStock = stock <= 0 || product.status === "inactive";

  const handleAddToCart = async (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();

    if (isOutOfStock) return;

    setIsAdding(true);
    await new Promise((resolve) => setTimeout(resolve, 300));

    addToCart({
      id: product.id,
      name: product.name,
      price: product.price,
      image: imageUrl,
      quantity: 1,
      stock,
    });

    setIsAdding(false);
    setJustAdded(true);
    setTimeout(() => setJustAdded(false), 2000);
  };

  const handleToggleLike = (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    toggleFavorite(product);
  };

  return (
    <Card className="group overflow-hidden bg-card border-border hover:shadow-lg transition-all duration-300 hover:-translate-y-1">
      <div className="relative overflow-hidden">
        <div
          className={cn(
            "absolute left-3 top-3 z-10 rounded-md px-2.5 py-1 text-xs font-semibold shadow-sm",
            isOutOfStock
              ? "bg-slate-900 text-white"
              : stock <= 10
                ? "bg-orange-100 text-orange-700"
                : "bg-emerald-50 text-emerald-700"
          )}
        >
          {isOutOfStock ? "Hết hàng" : "Còn hàng"}
        </div>

        <Button
          variant="ghost"
          size="icon"
          name="Like Button"
          className={cn(
            "absolute top-3 right-3 z-10 opacity-0 group-hover:opacity-100 transition-all duration-200 bg-background/80 backdrop-blur-sm hover:bg-background",
            isLiked && "opacity-100 text-destructive"
          )}
          onClick={handleToggleLike}
        >
          <Heart
            name="Like Icon"
            className={cn("h-4 w-4", isLiked && "fill-current")}
          />
        </Button>

        <Link href={`/product/${product.id}`} className="block relative">
          <div className="aspect-square overflow-hidden bg-muted">
            {!imageError ? (
              <Image
                src={imageUrl}
                alt={product.name}
                width={400}
                height={400}
                className={cn(
                  "w-full h-full object-cover transition-transform duration-300 group-hover:scale-105",
                  isOutOfStock && "opacity-60 grayscale"
                )}
                onError={() => setImageError(true)}
              />
            ) : (
              <div className="w-full h-full bg-muted flex items-center justify-center">
                <div className="text-muted-foreground text-sm">Chưa có hình ảnh</div>
              </div>
            )}
          </div>

          <div className="absolute inset-0 bg-background/60 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center gap-2">
            <Button size="sm" className="bg-primary text-primary-foreground hover:bg-primary/90">
              <Eye className="h-4 w-4 mr-2" />
              Xem nhanh
            </Button>
          </div>
        </Link>
      </div>

      <CardContent className="p-4 space-y-3">
        <Link href={`/product/${product.id}`}>
          <h2 className="font-semibold text-foreground line-clamp-2 hover:text-primary transition-colors">
            {product.name}
          </h2>
        </Link>

        <div className="flex items-center justify-between gap-2">
          <span className="text-lg font-bold text-foreground">
            {formatVND(product.price)}
          </span>
          {!isOutOfStock && stock <= 10 && (
            <span className="text-xs font-semibold text-orange-600">Sắp hết</span>
          )}
        </div>

        <Button
          className={cn(
            "w-full transition-all duration-300",
            isOutOfStock
              ? "bg-slate-300 text-slate-600 hover:bg-slate-300"
              : justAdded
                ? "bg-green-600 text-white hover:bg-green-600"
                : "bg-primary text-primary-foreground hover:bg-primary/90"
          )}
          onClick={handleAddToCart}
          disabled={isAdding || isOutOfStock}
        >
          {isOutOfStock ? (
            <div className="flex items-center gap-2">
              <ShoppingCart className="h-4 w-4" />
              Hết hàng
            </div>
          ) : isAdding ? (
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin" />
              Thêm...
            </div>
          ) : justAdded ? (
            <div className="flex items-center gap-2">
              <Check className="h-4 w-4" />
              Đã thêm!
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <ShoppingCart className="h-4 w-4" />
              Thêm vào giỏ
            </div>
          )}
        </Button>
      </CardContent>
    </Card>
  );
}
